	('cmlk2qb4o0009odx40a9ft754', '2', 'training-assist', 'gpt-4o-mini', 'e57ddb75b93d8af7683000e412d8bfe2c646a50c8507dae97925ab059f87d505', '{"title": "História da Apdata: Conhecendo Nossas Raízes e Valores", "description": "Neste treinamento, vamos explorar a trajetória da Apdata, desde sua fundação até os dias atuais. Entenderemos os valores que moldam nossa cultura e como a história da empresa impacta nosso trabalho diário. Venha se inspirar e fortalecer nossa equipe com o conhecimento sobre nossas origens!"}', '2026-02-12 23:12:29.4', '2026-02-13 23:12:29.398'),
	('cmlk2t7y7000dodx4h94w8u8k', '2', 'training-questions', 'gpt-4o-mini', 'd9c638f24ccd349c76dc3167ff981e0e7c3943d7ea97644938e7e46fe2a1f018', '{"questions": [{"tipo": "multipla-escolha", "pergunta": "Qual é o principal objetivo da história da Apdata?", "alternativas": ["Conhecer as raízes e valores da Apdata", "Aumentar as vendas da Apdata", "Expandir os serviços da Apdata", "Contratar novos colaboradores"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Quais valores são fundamentais para a Apdata?", "alternativas": ["Inovação, ética e compromisso", "Lucro, competitividade e crescimento", "Sustentabilidade, responsabilidade e eficiência", "Diversidade, inclusão e flexibilidade"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "A Apdata foi fundada em qual ano?", "alternativas": ["1985", "1990", "2000", "2010"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual foi o primeiro produto oferecido pela Apdata?", "alternativas": ["Software de gestão", "Consultoria em TI", "Treinamentos corporativos", "Soluções em nuvem"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Como a Apdata se posiciona no mercado?", "alternativas": ["Como líder em inovação tecnológica", "Como uma empresa focada em preços baixos", "Como uma startup em crescimento", "Como uma empresa tradicional"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual é a visão da Apdata para o futuro?", "alternativas": ["Ser referência em soluções tecnológicas", "Expandir para o mercado internacional", "Focar apenas em clientes locais", "Aumentar a equipe em 50%"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}]}', '2026-02-12 23:14:45.247', '2026-02-13 23:14:45.243'),
	('cmlk481en000zodx4158yq7mi', '2', 'training-questions', 'gpt-4o-mini', '1fc01e67145c1089a9d22c1304f06562edee0a4b8cd88ebb2ad60c70c9b1c81d', '{"questions": [{"tipo": "descritiva", "pergunta": "Qual é a importância da história da Apdata para a formação dos colaboradores?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Quais foram os principais marcos na evolução da Apdata ao longo dos anos?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Como a história da Apdata pode influenciar a cultura organizacional atual?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "De que maneira o conhecimento da história da Apdata pode impactar o desempenho dos colaboradores?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Quais lições podem ser aprendidas com a trajetória da Apdata que podem ser aplicadas no dia a dia dos colaboradores?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}]}', '2026-02-12 23:54:16.224', '2026-02-13 23:54:16.222'),
	('cmlkdtwy10007odls4qzebiny', '2', 'training-assist', 'gpt-4o-mini', '541efb87302de18b4d39bf59d3750bc5536b0b49df82c749fd85c06c8c18b574', '{"title": "Desenvolvendo a Inteligência Emocional no Ambiente de Trabalho", "description": "Neste treinamento, abordaremos estratégias práticas para aprimorar sua inteligência emocional, essencial para a convivência harmoniosa e produtiva no ambiente de trabalho. Aprenda a gerenciar suas emoções, melhorar a comunicação e fortalecer relacionamentos interpessoais."}', '2026-02-13 04:23:13.414', '2026-02-14 04:23:13.412'),
	('cmlkdx5h7000bodlslyslqjfv', '2', 'training-assist', 'gpt-4o-mini', '9e3ae812e414cfc5b4e9f1806a40d2181fc5032b8694ee9147b0131a32c2f943', '{"title": "Treinamento sobre a NR01: Normas de Segurança e Saúde no Trabalho", "description": "Participe do nosso treinamento sobre a NR01, que aborda as diretrizes fundamentais para garantir a segurança e a saúde no ambiente de trabalho. Aprenda sobre os principais riscos ocupacionais, medidas preventivas e a importância da cultura de segurança. Ideal para profissionais de todas as áreas!"}', '2026-02-13 04:25:44.443', '2026-02-14 04:25:44.441'),
	('cmlke1fut000fodlshk0obnk0', '2', 'training-summary', 'gpt-4o-mini', '5b91b2023894500540c48b20d4b7bb342c2ed42e20f4a8510694b8a5213cb49f', '{"summary": "A NR-01 estabelece diretrizes para segurança e saúde no trabalho, visando identificar, avaliar e controlar riscos ocupacionais para prevenir acidentes e doenças. O empregador deve cumprir normas de segurança, implementar o Gerenciamento de Riscos Ocupacionais (GRO), manter o Programa de Gerenciamento de Riscos (PGR) atualizado e informar os trabalhadores sobre riscos. Os colaboradores devem seguir normas de segurança, usar Equipamentos de Proteção Individual (EPI) e participar de treinamentos. O GRO envolve identificação de perigos, avaliação de riscos e implementação de medidas de prevenção. O PGR formaliza o gerenciamento de riscos e deve incluir um inventário de riscos e um plano de ação. Os treinamentos devem ser adequados aos riscos e registrados formalmente. Os trabalhadores têm direitos a um ambiente seguro e a recusar atividades de risco. A NR-01 é fundamental para a segurança no trabalho, enfatizando a responsabilidade compartilhada na prevenção de acidentes."}', '2026-02-13 04:29:04.517', '2026-02-14 04:29:04.516'),
	('cmlke4dbq000lodlsrwebtw5z', '2', 'training-questions', 'gpt-4o-mini', '37ffc3fde2b03f6dd73444b3e5653c27a0e9b10001a4c86724a69a6f36ac6fbc', '{"questions": [{"tipo": "multipla-escolha", "pergunta": "Qual é o principal objetivo da NR-01?", "alternativas": ["Identificar e avaliar riscos no ambiente de trabalho", "Estabelecer normas de conduta", "Criar um programa de treinamento", "Promover a saúde mental dos trabalhadores"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual documento formaliza o gerenciamento de riscos na empresa de acordo com a NR-01?", "alternativas": ["Programa de Prevenção de Riscos Ambientais (PPRA)", "Programa de Gerenciamento de Riscos (PGR)", "Norma Regulamentadora de Segurança (NRS)", "Documento de Controle de Riscos (DCR)"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 1}, {"tipo": "multipla-escolha", "pergunta": "Qual das seguintes responsabilidades é atribuída ao empregador segundo a NR-01?", "alternativas": ["Cumprir as normas de segurança", "Utilizar corretamente os EPIs", "Participar dos treinamentos obrigatórios", "Informar sobre riscos ao superior imediato"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "O que deve conter o Programa de Gerenciamento de Riscos (PGR)?", "alternativas": ["Apenas o inventário de riscos", "Um plano de ação com medidas preventivas", "A lista de todos os colaboradores", "Um cronograma de férias"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 1}, {"tipo": "multipla-escolha", "pergunta": "Os treinamentos sobre segurança no trabalho devem ser realizados:", "alternativas": ["Após o início das atividades", "Antes do início das atividades", "Somente uma vez por ano", "Apenas em casos de acidentes"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 1}]}', '2026-02-13 04:31:21.206', '2026-02-14 04:31:21.203'),
	('cmlke6o1k001oodls9e06rnro', '2', 'training-questions', 'gpt-4o-mini', '8d340ae4fa4e7ff5bf7e80fc92aa7a775c7f7e36e4afcd2e0676f573544b7a9c', '{"questions": [{"tipo": "multipla-escolha", "pergunta": "Qual é o principal objetivo da NR-01?", "alternativas": ["Garantir que as empresas identifiquem, avaliem e controlem os riscos existentes", "Estabelecer normas para a contratação de colaboradores", "Criar um programa de benefícios para os trabalhadores", "Definir penalidades para empresas que não cumprirem as normas"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Quais são algumas das responsabilidades do empregador segundo a NR-01?", "alternativas": ["Cumprir as normas de segurança e informar os trabalhadores sobre riscos", "Realizar a contratação de novos colaboradores", "Definir horários de trabalho", "Conceder férias aos empregados"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "O que deve conter o Programa de Gerenciamento de Riscos (PGR)?", "alternativas": ["Inventário de riscos e plano de ação", "Lista de colaboradores e suas funções", "Relatório financeiro da empresa", "Cronograma de férias dos colaboradores"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual é um dos direitos dos trabalhadores segundo a NR-01?", "alternativas": ["Recusar atividade que represente risco grave e iminente", "Receber bônus por desempenho", "Escolher o horário de trabalho", "Ter acesso a informações financeiras da empresa"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "O que caracteriza o Gerenciamento de Riscos Ocupacionais (GRO)?", "alternativas": ["Processo contínuo de identificação de perigos e avaliação de riscos", "Um sistema de recompensas para colaboradores", "Um método de avaliação de desempenho", "Um conjunto de normas administrativas"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}]}', '2026-02-13 04:33:08.408', '2026-02-14 04:33:08.405'),
	('cmlkecg9t003qodlsk9tfo89p', '2', 'training-questions', 'gpt-4o-mini', '0cf9d876fbfca90b24f1060ea7df6d67adbce7e2f7a733e919032cefd37f0fbe', '{"questions": [{"tipo": "descritiva", "pergunta": "Quais são as principais responsabilidades do empregador segundo a NR-01?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Descreva o processo de Gerenciamento de Riscos Ocupacionais (GRO) conforme definido na NR-01.", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Quais são os direitos dos trabalhadores em relação à segurança no trabalho segundo a NR-01?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Explique a importância do Programa de Gerenciamento de Riscos (PGR) na empresa.", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Quais são os requisitos que os treinamentos devem atender conforme a NR-01?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}]}', '2026-02-13 04:37:38.273', '2026-02-14 04:37:38.271'),
	('cmlkeqlgy000jod3grqzca5sk', '2', 'training-questions', 'gpt-4o-mini', '45774af77ff90e3d7bf3a667ffa713d06d9e6de6d8157fc1df5c1702b9ab4bce', '{"questions": [{"tipo": "descritiva", "pergunta": "Quais são as principais responsabilidades do empregador em relação à segurança no trabalho, conforme a NR-01?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Descreva o que é o Gerenciamento de Riscos Ocupacionais (GRO) e quais são suas etapas principais.", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Quais são os direitos dos trabalhadores em relação à segurança no ambiente de trabalho, segundo a NR-01?", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Explique a importância do Programa de Gerenciamento de Riscos (PGR) e o que ele deve conter.", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}, {"tipo": "descritiva", "pergunta": "Como os treinamentos devem ser realizados de acordo com a NR-01? Cite pelo menos três requisitos.", "alternativas": [], "tiposResposta": ["descritiva"], "alternativaCorreta": null}]}', '2026-02-13 04:48:38.195', '2026-02-14 04:48:38.193'),
	('cmlkswd140005odsctbfu8k2h', '1', 'training-assist', 'gpt-4o-mini', '1ba268d5273e985ee2609825d0f285892b432268003adb5dc063e40e1316ef1d', '{"title": "Comportamento Profissional: Guia para o Sucesso na Empresa", "description": "Este treinamento visa orientar André sobre as melhores práticas de comportamento no ambiente corporativo. Abordaremos tópicos como comunicação eficaz, trabalho em equipe, postura profissional e ética no trabalho. O objetivo é prepará-lo para interações produtivas e um desempenho exemplar na empresa."}', '2026-02-13 11:25:01.816', '2026-02-14 11:25:01.814'),
	('cmlkswz3d0009odscqxn3oa7k', '1', 'training-summary', 'gpt-4o-mini', '4b47cf572c44bd73ac810fc14b512ab64bb3880dc9f9b876699f43146ddd3c28', '{"summary": "A NR-01 define diretrizes para segurança e saúde no trabalho, visando identificar e controlar riscos ocupacionais para prevenir acidentes e doenças. O empregador deve cumprir normas de segurança, implementar o Gerenciamento de Riscos Ocupacionais (GRO), manter o Programa de Gerenciamento de Riscos (PGR) atualizado e capacitar os colaboradores. Os trabalhadores devem seguir normas de segurança, usar Equipamentos de Proteção Individual (EPI) e relatar riscos. O GRO envolve identificação de perigos, avaliação de riscos, implementação de medidas preventivas e monitoramento. O PGR formaliza o gerenciamento de riscos, incluindo inventário e plano de ação. Treinamentos devem ser adequados aos riscos e registrados. Os trabalhadores têm direitos a um ambiente seguro e a participar das ações de prevenção. A NR-01 é fundamental para a segurança no trabalho, enfatizando a responsabilidade compartilhada na prevenção de acidentes."}', '2026-02-13 11:25:30.41', '2026-02-14 11:25:30.408'),
	('cmlksyqaw000dodsc71f1zw31', '1', 'training-questions', 'gpt-4o-mini', '5888f24cab621c250f686594dd38da3c95da2972383165b08851b9fa5a3aff1a', '{"questions": [{"tipo": "multipla-escolha", "pergunta": "Qual é o principal objetivo da NR-01?", "alternativas": ["Garantir ambiente de trabalho seguro", "Reduzir custos operacionais", "Aumentar a produtividade", "Criar novas normas de trabalho"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual das seguintes responsabilidades é atribuída ao empregador de acordo com a NR-01?", "alternativas": ["Cumprir as normas de segurança", "Utilizar corretamente os EPIs", "Informar os riscos ao empregador", "Recusar atividades de risco"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "O que deve conter o Programa de Gerenciamento de Riscos (PGR)?", "alternativas": ["Apenas um inventário de riscos", "Um plano de ação com medidas preventivas", "Um cronograma de férias", "Um registro de funcionários"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 1}, {"tipo": "multipla-escolha", "pergunta": "Qual é uma das etapas do Gerenciamento de Riscos Ocupacionais (GRO)?", "alternativas": ["Identificação de perigos", "Aumento da carga horária", "Redução de custos", "Contratação de novos funcionários"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual é um dos direitos dos trabalhadores segundo a NR-01?", "alternativas": ["Recusar atividades sem aviso prévio", "Participar das ações de prevenção", "Não usar EPIs", "Trabalhar em qualquer ambiente"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 1}, {"tipo": "multipla-escolha", "pergunta": "Quando os treinamentos devem ser realizados de acordo com a NR-01?", "alternativas": ["Após o início das atividades", "Antes do início das atividades", "Somente uma vez por ano", "Quando o empregador achar ne