	('cmlkx3b90000xodfwb6fbn9we', '2', 'training-assist', 'gpt-4o-mini', '65f46131a85742c6efe01695eac3450ca5be4c246d6a788b5977d4d289b24cc8', '{"title": "Treinamento NR1: Fundamentos e Aplicações para a Equipe Apdata", "description": "Participe do treinamento sobre a Norma Regulamentadora NR1, que aborda os princípios básicos de segurança e saúde no trabalho. Este curso é essencial para a equipe da Apdata, proporcionando conhecimento sobre as diretrizes que garantem um ambiente de trabalho seguro e saudável. Venha aprimorar suas habilidades e entender a importância da NR1 na prática diária."}', '2026-02-13 13:22:24.564', '2026-02-14 13:22:24.563'),
	('cmlkx40rv0011odfw99nqn158', '2', 'training-questions', 'gpt-4o-mini', '6600802c20f038d0727a55c192cf626fefb13b7d4778176d67765558b6a2128d', '{"questions": [{"tipo": "multipla-escolha", "pergunta": "Qual é o principal objetivo da NR-01?", "alternativas": ["Garantir que as empresas identifiquem, avaliem e controlem os riscos existentes no ambiente de trabalho", "Estabelecer um cronograma de férias para os trabalhadores", "Criar um programa de incentivo para os colaboradores", "Implementar um sistema de avaliação de desempenho"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Quais são as responsabilidades do empregador segundo a NR-01?", "alternativas": ["Cumprir normas de segurança e fornecer EPIs", "Realizar reuniões mensais com os colaboradores", "Promover eventos sociais para a equipe", "Contratar novos funcionários"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "O que deve conter o Programa de Gerenciamento de Riscos (PGR)?", "alternativas": ["Inventário de riscos e plano de ação", "Lista de funcionários e suas funções", "Relatórios de produtividade", "Planos de carreira"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual é uma das etapas do Gerenciamento de Riscos Ocupacionais (GRO)?", "alternativas": ["Identificação de perigos", "Contratação de novos colaboradores", "Realização de festas de confraternização", "Avaliação de desempenho"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Quais são os direitos dos trabalhadores conforme a NR-01?", "alternativas": ["Ter um ambiente de trabalho seguro e informações claras sobre riscos", "Receber bônus por produtividade", "Escolher o horário de trabalho", "Participar de eventos de lazer"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}]}', '2026-02-13 13:22:57.643', '2026-02-14 13:22:57.641'),
	('cmlkyfgq1001kodfwvhgwl4yf', '1', 'training-assist', 'gpt-4o-mini', '68e335165bfc06d535e6666370544f028e165dc1b638bb81bde8b92563ef78f2', '{"title": "Treinamento de Vendas para Otime Comercial da Apdata", "description": "Este treinamento visa capacitar o time comercial da Apdata a alcançar suas metas de vendas do módulo de treinamento. Através de técnicas de vendas, estratégias de negociação e conhecimento aprofundado do produto, os participantes aprenderão a maximizar resultados e a se destacar no mercado."}', '2026-02-13 13:59:51.145', '2026-02-14 13:59:51.143'),
	('cmlkyl7j1001qodfwkptfcgnt', '1', 'training-questions', 'gpt-4o-mini', 'c9c2031bc8c880b34d768b5b43e90f51eb1b79ac1c7be0fec2252b02cc83d359', '{"questions": [{"tipo": "multipla-escolha", "pergunta": "Qual é o principal objetivo da NR-01?", "alternativas": ["Garantir a segurança e saúde no trabalho", "Aumentar a produtividade dos colaboradores", "Reduzir custos operacionais", "Promover a integração entre equipes"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Quais são as responsabilidades do empregador segundo a NR-01?", "alternativas": ["Cumprir as normas de segurança e informar os trabalhadores", "Realizar reuniões mensais com os colaboradores", "Aumentar a jornada de trabalho", "Criar um ambiente de competição entre os trabalhadores"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "O que deve conter o Programa de Gerenciamento de Riscos (PGR)?", "alternativas": ["Inventário de riscos e plano de ação", "Lista de funcionários e suas funções", "Relatório financeiro da empresa", "Estratégias de marketing"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Qual é a primeira etapa do Gerenciamento de Riscos Ocupacionais (GRO)?", "alternativas": ["Identificação de perigos", "Avaliação de riscos", "Implementação de medidas de prevenção", "Monitoramento e melhoria contínua"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}, {"tipo": "multipla-escolha", "pergunta": "Quais são os direitos dos trabalhadores conforme a NR-01?", "alternativas": ["Recusar atividade que represente risco grave", "Participar de eventos sociais da empresa", "Receber bônus por produtividade", "Ter acesso a informações financeiras"], "tiposResposta": ["multipla-escolha"], "alternativaCorreta": 0}]}', '2026-02-13 14:04:19.166', '2026-02-14 14:04:19.164'),
	('cmlkyv31z001uodfw4rctadao', '1', 'training-assist', 'gpt-4o-mini', '3f4dbe4db66134bd870c974aa9ce506b52a0dbb100d2fb49443dd1af38e7c228', '{"title": "Treinamento sobre NR1: Introdução às Normas Regulamentadoras", "description": "Participe do nosso treinamento sobre a NR1, que aborda as diretrizes fundamentais das Normas Regulamentadoras. Aprenda sobre a importância da segurança no trabalho, os direitos e deveres dos trabalhadores e empregadores, e como implementar práticas seguras no dia a dia da sua equipe."}', '2026-02-13 14:11:59.927', '2026-02-14 14:11:59.925'),
	('cmlkzttqw002yodfwzs73zb7c', '2', 'training-summary', 'gpt-4o-mini', '09a72ecb96cc3ae9f87a314df00075be3242375d0283a3d4eae8bab45bbda80b', '{"summary": "A NR-01 define diretrizes para segurança e saúde no trabalho, visando identificar, avaliar e controlar riscos ocupacionais. O empregador deve cumprir normas de segurança, implementar o Gerenciamento de Riscos Ocupacionais (GRO), manter o Programa de Gerenciamento de Riscos (PGR) atualizado e capacitar os trabalhadores. Os colaboradores devem seguir normas de segurança, usar Equipamentos de Proteção Individual (EPI) e participar de treinamentos. O GRO envolve identificação de perigos, avaliação de riscos e implementação de medidas preventivas. O PGR formaliza o gerenciamento de riscos, incluindo inventário e plano de ação. Treinamentos devem ser adequados aos riscos e registrados. Os trabalhadores têm direitos a um ambiente seguro e a recusar atividades de risco. A NR-01 é fundamental para a segurança no trabalho, enfatizando a responsabilidade compartilhada na prevenção de acidentes."}', '2026-02-13 14:39:00.753', '2026-02-14 14:39:00.752'),
	('cmlkzvkw30032odfwpl3vjo52', '2', 'training-summary', 'gpt-4o-mini', 'fe9dbf08b58ae532934d76632c92ea1f35da608f9eb09038c4a9765ec09ac807', '{"summary": "A NR-01 define diretrizes gerais para segurança e saúde no trabalho, visando a identificação, avaliação e controle de riscos ocupacionais para prevenir acidentes e doenças. O empregador deve cumprir normas de segurança, implementar o Gerenciamento de Riscos Ocupacionais (GRO), manter o Programa de Gerenciamento de Riscos (PGR) atualizado, informar e capacitar os trabalhadores, além de fornecer Equipamentos de Proteção Individual (EPI). Os trabalhadores devem seguir normas de segurança, usar EPIs, participar de treinamentos e relatar riscos. O GRO envolve identificação de perigos, avaliação de riscos, implementação de medidas preventivas e monitoramento contínuo. O PGR formaliza o gerenciamento de riscos e inclui inventário de riscos, plano de ação e cronograma. Os treinamentos devem ser adequados aos riscos, realizados antes das atividades e registrados. Os trabalhadores têm direito a um ambiente seguro, informações sobre riscos, recusa de atividades perigosas e participação nas ações de prevenção. A NR-01 é fundamental para a segurança no trabalho, enfatizando que a prevenção é essencial."}', '2026-02-13 14:40:22.659', '2026-02-14 14:40:22.657');
