INSERT INTO "trainings" ("id", "title", "description", "coverType", "coverUrl", "primaryColor", "campaignId", "contentOrigin", "contentText", "contentFiles", "noAssessment", "convertContent", "conversionType", "allowOriginal", "summaryPercent", "summaryText", "summaryConfirmed", "aiConfig", "aiConversions", "visibleFormats", "questionsRequired", "requireSequential", "audienceType", "audienceIds", "startDate", "endDate", "rewardsActive", "rewardXP", "rewardStars", "creatorId", "createdAt", "updatedAt", "deletedAt") VALUES
	('cmlkx2fn2000qodfw9qybkps1', 'Treinamento sobre Política Comercial para a Equipe Apdata', 'Participe do nosso treinamento sobre Política Comercial, desenvolvido especialmente para a equipe Apdata. Neste curso, você irá aprender sobre as diretrizes e práticas essenciais que regem nossas operações comerciais, visando a melhoria do desempenho e a maximização de resultados. Não perca a oportunidade de aprimorar suas habilidades e alinhar sua atuação com as estratégias da empresa!', 'upload', 'trainings/2/1770988903011-capa.png', '#72aa8b', NULL, 'documento', '', '{trainings/2/1770988881992-politica_comercial_apdata.txt}', 'false', 'false', NULL, 'false', 0, NULL, 'false', '{"quantidade": 5, "dificuldade": "intermediario", "resumoAtivo": false, "tipoQuestoes": "multipla-escolha", "resumoPercentual": 50}', '{}', '{}', 'true', 'false', 'todo_time', '{}', '2026-02-13 00:00:00', '2026-02-27 00:00:00', 'true', 100, 30, '2', '2026-02-13 13:21:43.598', '2026-02-13 13:21:43.598', NULL),
	('cmlkx4b560015odfwg0yfktzf', 'Treinamento NR1: Fundamentos e Aplicações para a Equipe Apdata', 'Participe do treinamento sobre a Norma Regulamentadora NR1, que aborda os princípios básicos de segurança e saúde no trabalho. Este curso é essencial para a equipe da Apdata, proporcionando conhecimento sobre as diretrizes que garantem um ambiente de trabalho seguro e saudável. Venha aprimorar suas habilidades e entender a importância da NR1 na prática diária.', 'upload', 'trainings/2/1770988990557-capa.jpeg', '#fec408', NULL, 'documento', '', '{trainings/2/1770988963269-TESTE.txt}', 'false', 'false', NULL, 'false', 0, NULL, 'false', '{"quantidade": 5, "dificuldade": "intermediario", "resumoAtivo": false, "tipoQuestoes": "multipla-escolha", "tipoResposta": "multipla-escolha", "resumoPercentual": 50}', '{}', '{}', 'true', 'false', 'todo_time', '{}', '2026-02-13 00:00:00', '2026-02-20 00:00:00', 'true', 100, 30, '2', '2026-02-13 13:23:11.081', '2026-02-13 13:23:11.081', NULL);
